CARDIO.register({"item":"p209","meta":{"num":"p209","label":"209","spe":"pneumo","short":"BPCO","title":"Bronchopneumopathie chronique obstructive (BPCO)","section":"P","chapter":13,"pages":"187-209","sdd":[]},"objectives":[{"id":"p209-obj-01","rank":"B","rubric":"Contenu multimédia","title":"Exemple de radiographie thoracique BPCO","desc":""},{"id":"p209-obj-02","rank":"A","rubric":"Définition","title":"Connaître la définition de la BPCO, de la bronchite chronique et de l'emphysème","desc":""},{"id":"p209-obj-03","rank":"A","rubric":"Définition","title":"Connaître le principal facteur de risque et les comorbidités fréquemment associées à la BPCO","desc":""},{"id":"p209-obj-04","rank":"B","rubric":"Épidémiologie","title":"Connaître l'épidémiologie de la BPCO","desc":""},{"id":"p209-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Connaître les éléments du diagnostic positif et du diagnostic différentiel","desc":""},{"id":"p209-obj-06","rank":"B","rubric":"Étiologies","title":"Connaître les facteurs précipitants d'une exacerbation de BPCO","desc":""},{"id":"p209-obj-07","rank":"A","rubric":"Examens complémentaires","title":"Savoir rechercher les signes paracliniques de sévérité (long cours) / gravité (aigu)","desc":""},{"id":"p209-obj-08","rank":"B","rubric":"Examens complémentaires","title":"Savoir monitorer la tolérance du traitement","desc":""},{"id":"p209-obj-09","rank":"B","rubric":"Examens complémentaires","title":"Connaître les indications des examens d'imagerie devant une BPCO","desc":""},{"id":"p209-obj-10","rank":"B","rubric":"Examens complémentaires","title":"Connaître l'objectif de l'imagerie dans l'exploration d'une bronchopneumopathie chronique obstructive","desc":""},{"id":"p209-obj-11","rank":"B","rubric":"Examens complémentaires","title":"Connaître la sémiologie radiologique d'une bronchopneumopathie chronique obstructive","desc":""},{"id":"p209-obj-12","rank":"A","rubric":"Identification de l'urgence","title":"Identifier une exacerbation/décompensation de BPCO, en évaluer les signes de gravité","desc":""},{"id":"p209-obj-13","rank":"A","rubric":"Prise en charge","title":"Connaître les principes de l'initiation du traitement symptomatique en urgence","desc":""},{"id":"p209-obj-14","rank":"A","rubric":"Prise en charge","title":"Connaître les principes de prise en charge de l'exacerbation et du traitement de fond","desc":""},{"id":"p209-obj-15","rank":"B","rubric":"Prise en charge","title":"Savoir monitorer la tolérance du traitement","desc":""},{"id":"p209-obj-16","rank":"B","rubric":"Examens complémentaires","title":"Connaître l'objectif de l'imagerie dans l'exploration d'une BPCO","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p209-qroc-001","type":"QROC","rank":"A","objective":"p209-obj-02","tags":["définition"],"difficulty":1,"question":"Quels sont les deux critères qui définissent la BPCO ?","answer":"Symptômes respiratoires chroniques + TVO non complètement réversible","accept":["symptômes respiratoires chroniques et TVO non complètement réversible","symptômes chroniques et obstruction bronchique non complètement réversible","symptômes respiratoires chroniques et trouble ventilatoire obstructif"],"keywords":["symptôme","réversible"],"explanation":"Les symptômes sont au moins un parmi toux, expectoration, dyspnée d'effort, infections respiratoires basses répétées ou traînantes ; l'obstruction persiste après bronchodilatateur.","src":"p. 188-189"},{"id":"p209-qroc-002","type":"QROC","rank":"A","objective":"p209-obj-02","tags":["définition","paraclinique"],"difficulty":1,"question":"Quelle valeur seuil du rapport VEMS/CVF, mesuré après bronchodilatateur, définit le trouble ventilatoire obstructif de la BPCO ?","answer":"0,7 (70 %)","accept":["0,7","70 %","70","< 0,7"],"keywords":["0,7"],"explanation":"Le TVO doit persister après bronchodilatateur : VEMS/CVF < 0,7 (ou < 70 %).","src":"p. 188-189"},{"id":"p209-qroc-003","type":"QROC","rank":"A","objective":"p209-obj-02","tags":["paraclinique","pièges"],"difficulty":2,"question":"À quoi correspond le pourcentage du rapport VEMS/CVF utilisé pour définir le TVO (piège classique) ?","answer":"VEMS mesuré / CVF mesurée × 100, et non un % de la valeur théorique","accept":["rapport VEMS mesuré sur CVF mesurée","VEMS/CVF mesurés"],"keywords":["mesur"],"explanation":"Le pourcentage obtenu est le rapport VEMS mesuré / CVF mesurée (× 100) ; il ne s'agit pas d'un pourcentage d'une valeur théorique.","trap":"70 % de VEMS/CVF ≠ 70 % de la valeur prédite.","src":"p. 189, 197"},{"id":"p209-qroc-004","type":"QROC","rank":"A","objective":"p209-obj-05","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Quel examen, réalisé à l'état stable avant et après bronchodilatateur, est obligatoire pour poser le diagnostic de BPCO ?","answer":"La spirométrie","accept":["spirométrie","spirométrie avec test de réversibilité","EFR avec test aux bronchodilatateurs"],"keywords":["spirom"],"explanation":"Elle mesure le VEMS et la CVF ; réalisée en dehors d'une exacerbation, elle permet le diagnostic de certitude et aide au diagnostic différentiel avec l'asthme.","src":"p. 189, 197"},{"id":"p209-qroc-005","type":"QROC","rank":"A","objective":"p209-obj-02","tags":["définition","clinique"],"difficulty":1,"question":"Comment définit-on la bronchite chronique ?","answer":"Toux productive quotidienne ≥ 3 mois par an pendant ≥ 2 années consécutives","accept":["toux productive 3 mois par an pendant 2 ans","toux et expectoration 3 mois par an pendant 2 années consécutives"],"keywords":["toux","3 mois","2 an"],"explanation":"Sa définition est purement clinique ; elle concerne environ la moitié des fumeurs et n'entre dans la BPCO que si elle s'associe à un TVO.","src":"p. 189-190"},{"id":"p209-qroc-006","type":"QROC","rank":"A","objective":"p209-obj-02","tags":["définition","physiopathologie"],"difficulty":2,"question":"Quelle est la définition (anatomopathologique) de l'emphysème ?","answer":"Élargissement permanent des espaces aériens distaux avec destruction alvéolaire","accept":["élargissement anormal et permanent des espaces aériens distaux avec destruction des parois alvéolaires","destruction des parois alvéolaires avec élargissement permanent des espaces aériens distaux"],"keywords":["permanent","destruction"],"explanation":"Il n'y a pas de fibrose associée ; un emphysème sans TVO n'entre pas dans la définition de la BPCO. On le suspecte sur la radiographie et on l'affirme au scanner (hypodensités).","src":"p. 190"},{"id":"p209-qroc-007","type":"QROC","rank":"A","objective":"p209-obj-03","tags":["étiologie","épidémiologie"],"difficulty":1,"question":"Quel est le principal facteur de risque de BPCO en France ?","answer":"Le tabagisme","accept":["tabagisme","tabac","tabagisme actif"],"keywords":["tabag"],"explanation":"Plus de 80 % des patients atteints de BPCO en France sont fumeurs ; des expositions professionnelles peuvent aussi être en cause.","src":"p. 188, 194"},{"id":"p209-qroc-008","type":"QROC","rank":"A","objective":"p209-obj-03","tags":["complications"],"difficulty":2,"question":"Quelles sont les trois principales causes de mortalité chez les patients atteints de BPCO ?","answer":"Accidents ischémiques, cancer bronchique, insuffisance respiratoire aiguë","accept":["accidents ischémiques (cardiaques et neurologiques), cancer bronchique, insuffisance respiratoire aiguë","accidents ischémiques cardiaques et neurologiques, cancer bronchique, IRA"],"keywords":["ischémi","cancer","insuffisance respiratoire"],"explanation":"Les comorbidités cardio-vasculaires et le cancer bronchique sont fréquents et doivent être recherchés systématiquement.","src":"p. 196, 199"},{"id":"p209-qroc-009","type":"QROC","rank":"A","objective":"p209-obj-05","tags":["clinique"],"difficulty":1,"question":"Quel est le symptôme principal de la BPCO, tardif et souvent sous-estimé par le patient ?","answer":"La dyspnée d'effort","accept":["dyspnée","dyspnée d'effort","essoufflement"],"keywords":["dyspn"],"explanation":"Elle survient d'abord pour des efforts importants, puis pour des efforts de moins en moins importants ; elle est à rechercher chez tout fumeur.","src":"p. 188, 196"},{"id":"p209-qroc-010","type":"QROC","rank":"A","objective":"p209-obj-05","tags":["clinique","pièges"],"difficulty":2,"question":"Que montre souvent l'examen physique pendant des années au cours de la BPCO ?","answer":"Rien, ou seulement des râles bronchiques (ronchi)","accept":["rien","examen normal","absence de signes","ronchi","râles bronchiques"],"keywords":["ronchi"],"explanation":"Les signes de distension, d'obstruction ou de dysfonction diaphragmatique (diminution du murmure vésiculaire, sibilants) apparaissent souvent après le TVO.","src":"p. 196"},{"id":"p209-qroc-011","type":"QROC","rank":"A","objective":"p209-obj-05","tags":["diagnostic"],"difficulty":1,"question":"Quels sont les deux principaux diagnostics différentiels de la BPCO ?","answer":"L'asthme et la dilatation des bronches","accept":["asthme et dilatation des bronches","asthme et DDB","asthme, dilatation des bronches"],"keywords":["asthm","dilatation"],"explanation":"Les deux maladies peuvent être associées ; l'asthme existe chez les fumeurs, et des dilatations des bronches modérées s'observent chez des patients BPCO.","src":"p. 188, 191"},{"id":"p209-qroc-012","type":"QROC","rank":"A","objective":"p209-obj-05","tags":["diagnostic","paraclinique"],"difficulty":2,"question":"Quelle augmentation du VEMS après bronchodilatateur définit une réversibilité significative du TVO ?","answer":"Plus de 200 mL ET plus de 12 % par rapport à la valeur initiale","accept":["200 ml et 12 %","> 200 ml et > 12 %"],"keywords":["200","12"],"explanation":"Une réversibilité significative est évocatrice d'un asthme mais peut être observée dans la BPCO.","src":"p. 189"},{"id":"p209-qroc-013","type":"QROC","rank":"A","objective":"p209-obj-05","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quel diagnostic est orienté, et lequel est écarté, si le rapport VEMS/CVF se normalise (> 0,7) après bronchodilatateur ?","answer":"Asthme orienté ; BPCO écartée","accept":["asthme","asthme, pas de BPCO","asthme et non BPCO"],"keywords":["asthm"],"explanation":"Une réversibilité complète du TVO (normalisation du rapport VEMS/CVF) écarte le diagnostic de BPCO.","src":"p. 189"},{"id":"p209-qroc-014","type":"QROC","rank":"A","objective":"p209-obj-07","tags":["paraclinique"],"difficulty":2,"question":"Quel grade de sévérité GOLD correspond à un VEMS post-bronchodilatateur à 40 % de la valeur prédite, avec un rapport VEMS/CVF < 70 % ?","answer":"GOLD 3 (obstruction sévère)","accept":["GOLD 3","grade 3","stade 3","3"],"keywords":["3"],"explanation":"Le grade GOLD 3 correspond à un VEMS post-BD entre 30 et 49 % de la valeur prédite : obstruction bronchique sévère.","src":"p. 192"},{"id":"p209-qroc-015","type":"QROC","rank":"A","objective":"p209-obj-07","tags":["paraclinique"],"difficulty":1,"question":"En dessous de quelle valeur de VEMS post-bronchodilatateur (en % de la valeur prédite) l'obstruction est-elle très sévère (GOLD 4) ?","answer":"30 %","accept":["30 %","30","30 pour cent"],"keywords":["30"],"explanation":"La classification GOLD 1-2-3-4 porte sur la sévérité fonctionnelle respiratoire, jugée sur le VEMS après bronchodilatateurs.","src":"p. 192"},{"id":"p209-qroc-016","type":"QROC","rank":"A","objective":"p209-obj-07","tags":["clinique","paraclinique"],"difficulty":1,"question":"Quelle échelle évalue l'importance de la dyspnée d'effort dans la classification clinique GOLD A-B-E ?","answer":"L'échelle mMRC","accept":["mmrc","échelle mmrc"],"keywords":["mmrc"],"explanation":"La classification A-B-E associe la dyspnée d'effort (mMRC) et la fréquence des exacerbations.","src":"p. 192-193"},{"id":"p209-qroc-017","type":"QROC","rank":"A","objective":"p209-obj-07","tags":["paraclinique"],"difficulty":2,"question":"Quels critères d'exacerbations définissent le groupe E de la classification GOLD ?","answer":"≥ 2 exacerbations par an, ou ≥ 1 avec hospitalisation","accept":["2 exacerbations par an ou 1 avec hospitalisation","≥ 2/an ou ≥ 1/an avec hospitalisation"],"keywords":["2","hospitalis"],"explanation":"C'est le phénotype exacerbateur fréquent, facteur de mauvais pronostic ; les anciennes classes C et D ont été réunies en « E ».","src":"p. 193"},{"id":"p209-qroc-018","type":"QROC","rank":"A","objective":"p209-obj-07","tags":["paraclinique","pièges"],"difficulty":1,"question":"Quelle exploration paraclinique est justifiée dans une exacerbation légère ou modérée prise en charge en ville ?","answer":"Aucune","accept":["aucune","aucun examen","pas d'exploration"],"keywords":["aucun"],"explanation":"La majorité des exacerbations ne s'accompagne pas de signe de gravité et peut être prise en charge en ville.","src":"p. 205"},{"id":"p209-qroc-019","type":"QROC","rank":"A","objective":"p209-obj-07","tags":["biologie","urgence"],"difficulty":1,"question":"Quel examen permet d'apprécier la gravité d'une exacerbation sévère en recherchant une acidose respiratoire ?","answer":"La gazométrie artérielle","accept":["gazométrie","gaz du sang","gaz du sang artériel"],"keywords":["gaz"],"explanation":"Chez le patient hospitalisé, on réalise en systématique : radiographie thoracique, ECG, NFS, CRP, ionogramme-créatinine et gazométrie artérielle.","src":"p. 205-206"},{"id":"p209-qroc-020","type":"QROC","rank":"A","objective":"p209-obj-14","tags":["traitement","prévention"],"difficulty":1,"question":"Quelle est la seule mesure qui modifie de façon certaine l'histoire naturelle de la BPCO ?","answer":"Le sevrage tabagique total et définitif","accept":["sevrage tabagique","arrêt du tabac","arrêt du tabagisme"],"keywords":["sevrage"],"explanation":"Il interrompt la progression de l'obstruction bronchique et retarde l'insuffisance respiratoire et le décès, quel que soit le stade de la maladie.","src":"p. 199-200, 201"},{"id":"p209-qroc-021","type":"QROC","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":1,"question":"Quelle est la séquence du traitement médicamenteux de fond de la BPCO ?","answer":"Bronchodilatateur, puis bithérapie, puis éventuellement trithérapie","accept":["bronchodilatateur, bithérapie, trithérapie","monothérapie bronchodilatatrice puis bithérapie puis trithérapie"],"keywords":["bronchodilat","trith"],"explanation":"Les indications médicamenteuses dépendent des symptômes (dyspnée) et des exacerbations, indépendamment de la sévérité de l'obstruction bronchique.","src":"p. 200"},{"id":"p209-qroc-022","type":"QROC","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":1,"question":"Quelles sont les deux familles de bronchodilatateurs utilisées dans la BPCO ?","answer":"Anticholinergiques (antimuscariniques) et bêta-2-agonistes","accept":["anticholinergiques et bêta-2-agonistes","antimuscariniques et bêta-2 mimétiques","anticholinergiques et bêta-2-mimétiques"],"keywords":["anticholin","bêta"],"explanation":"Les bronchodilatateurs de longue durée d'action sont efficaces sur la dyspnée, la capacité d'exercice, les exacerbations et la qualité de vie ; seule la voie inhalée est recommandée.","src":"p. 201-202"},{"id":"p209-qroc-023","type":"QROC","rank":"A","objective":"p209-obj-14","tags":["traitement","pièges"],"difficulty":2,"question":"Quel traitement inhalé, indiqué en monothérapie dans l'asthme, n'est pas indiqué en traitement de fond de la BPCO ?","answer":"Les corticostéroïdes inhalés en monothérapie","accept":["corticostéroïdes inhalés","corticoïdes inhalés","CSI","corticothérapie inhalée"],"keywords":["cortico"],"explanation":"Ils ne sont utilisés qu'en association avec un bêta-2-agoniste de longue durée d'action chez certains patients exacerbateurs.","src":"p. 202"},{"id":"p209-qroc-024","type":"QROC","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":2,"question":"Chez quels patients associe-t-on corticostéroïde inhalé et bêta-2-agoniste de longue durée d'action ?","answer":"Exacerbateurs fréquents (≥ 2/an) malgré un traitement régulier par BDLA","accept":["exacerbateurs fréquents","≥ 2 exacerbations par an malgré les bronchodilatateurs de longue durée d'action"],"keywords":["exacerbat"],"explanation":"Cette association réduit les symptômes et les exacerbations, mais expose à un risque accru d'infections respiratoires parenchymateuses.","src":"p. 202"},{"id":"p209-qroc-025","type":"QROC","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":2,"question":"Quand envisage-t-on une triple thérapie (bêta-2-agoniste + anticholinergique + corticostéroïde inhalé) ?","answer":"En cas de persistance d'exacerbations malgré une bithérapie","accept":["exacerbations persistantes malgré une bithérapie","persistance des exacerbations sous bithérapie","malgré un traitement double"],"keywords":["exacerbation"],"explanation":"Elle est indiquée chez les patients restant symptomatiques et/ou ayant des exacerbations malgré un traitement double.","src":"p. 188, 202"},{"id":"p209-qroc-026","type":"QROC","rank":"A","objective":"p209-obj-14","tags":["prévention","traitement"],"difficulty":1,"question":"Quels vaccins sont recommandés chez tout patient atteint de BPCO ?","answer":"Grippe (annuelle), pneumocoque, COVID-19","accept":["grippe, pneumocoque, covid-19","antigrippal, antipneumococcique, anti-covid"],"keywords":["grippe","pneumoco","covid"],"explanation":"La vaccination contre la COVID-19 est indiquée chez tous les patients atteints de BPCO ; il faut tracer les vaccinations anti-pneumococciques.","src":"p. 188, 202"},{"id":"p209-qroc-027","type":"QROC","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":2,"question":"À partir de quand la réadaptation respiratoire est-elle recommandée chez un patient atteint de BPCO ?","answer":"Dès qu'il existe un handicap (même une dyspnée seule) malgré le traitement","accept":["dès qu'il existe un handicap malgré le traitement pharmacologique","dyspnée ou handicap persistant"],"keywords":["handicap"],"explanation":"Elle comprend notamment le réentraînement à l'exercice, l'éducation thérapeutique, la prise en charge nutritionnelle et psychosociale.","src":"p. 203"},{"id":"p209-qroc-028","type":"QROC","rank":"A","objective":"p209-obj-12","tags":["définition","urgence"],"difficulty":2,"question":"En combien de temps l'aggravation de la dyspnée, de la toux et/ou de l'expectoration doit-elle s'installer pour parler d'exacerbation aiguë de BPCO ?","answer":"En moins de 14 jours","accept":["14 jours","moins de 14 jours","< 14 jours"],"keywords":["14"],"explanation":"Elle peut s'associer à une tachypnée et/ou une tachycardie, et à une inflammation locale et systémique liée à une infection, à la pollution ou à une autre agression des voies aériennes.","src":"p. 189, 204"},{"id":"p209-qroc-029","type":"QROC","rank":"A","objective":"p209-obj-12","tags":["urgence","complications"],"difficulty":2,"question":"Quels deux éléments peuvent engager le pronostic vital lors d'une exacerbation sévère de BPCO ?","answer":"Hypoxémie profonde et/ou acidose respiratoire décompensée (pH ≤ 7,35)","accept":["hypoxémie profonde et acidose respiratoire décompensée","hypoxémie et acidose respiratoire"],"keywords":["hypox","acidose"],"explanation":"Les exacerbations sévères sont celles qui nécessitent une hospitalisation ; une assistance respiratoire (oxygénothérapie, ventilation assistée) est alors souvent nécessaire.","src":"p. 204"},{"id":"p209-qroc-030","type":"QROC","rank":"A","objective":"p209-obj-13","tags":["étiologie","diagnostic"],"difficulty":1,"question":"Quel est le principal argument en faveur d'une infection bactérienne au cours d'une exacerbation de BPCO ?","answer":"La purulence de l'expectoration","accept":["expectoration purulente","purulence","crachats purulents"],"keywords":["purulen"],"explanation":"Elle oriente vers une antibiothérapie ; les virus sont aussi fréquemment en cause.","src":"p. 188, 205"},{"id":"p209-qroc-031","type":"QROC","rank":"A","objective":"p209-obj-13","tags":["traitement","urgence"],"difficulty":1,"question":"Quel traitement est essentiel dans l'exacerbation de BPCO, administré exclusivement par voie inhalée ?","answer":"Les bronchodilatateurs","accept":["bronchodilatateurs","bronchodilatateur","bêta-2 agonistes de courte durée d'action"],"keywords":["bronchodilat"],"explanation":"Bêta-2-agonistes de courte durée d'action en première intention, seuls ou associés à un anticholinergique de courte durée d'action ; à l'hôpital, la nébulisation est le mode privilégié.","src":"p. 206"},{"id":"p209-qroc-032","type":"QROC","rank":"A","objective":"p209-obj-13","tags":["traitement","urgence"],"difficulty":1,"question":"Entre quelles valeurs titre-t-on la saturation pulsée en oxygène (SpO2) lors de l'oxygénothérapie d'une exacerbation de BPCO ?","answer":"88 à 92 %","accept":["88-92 %","88 et 92","88 à 92","entre 88 et 92 %"],"keywords":["88","92"],"explanation":"L'hypoxémie mal tolérée ou profonde reste un signe de gravité majeur à corriger ; en cas d'hypercapnie, une surveillance gazométrique détecte les patients chez qui l'oxygène aggrave l'acidose.","src":"p. 188, 207"},{"id":"p209-qroc-033","type":"QROC","rank":"A","objective":"p209-obj-13","tags":["traitement","urgence"],"difficulty":2,"question":"Quel seuil de pH impose une assistance ventilatoire au cours d'une exacerbation de BPCO, et quel mode est proposé en première intention ?","answer":"pH < 7,35 (acidose respiratoire) ; ventilation non invasive (masque facial)","accept":["acidose respiratoire, ventilation non invasive","pH < 7,35, VNI","pH < 7,35, ventilation non invasive"],"keywords":["7,35","non invasive"],"explanation":"La ventilation mécanique est indiquée en cas d'acidose respiratoire ; en première intention, une ventilation non invasive est proposée par un masque facial.","src":"p. 208"},{"id":"p209-qroc-034","type":"QROC","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":2,"question":"Dans quels cas prescrit-on une antibiothérapie au cours d'une exacerbation de BPCO ?","answer":"Expectoration franchement purulente, VEMS < 30 %, ou signes de gravité","accept":["expectoration purulente, BPCO très sévère, signes de gravité","purulence franche, VEMS < 30 %, signes cliniques de gravité"],"keywords":["purulen","30","gravit"],"explanation":"En première intention : amoxicilline ± acide clavulanique, pristinamycine ou macrolides ; durée de 5 à 7 jours, réévaluée à J2-J3.","src":"p. 206-207"},{"id":"p209-qroc-035","type":"QROC","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":2,"question":"Quelles sont la dose et la durée d'une corticothérapie systémique à l'hôpital au cours d'une exacerbation de BPCO ?","answer":"30-40 mg/j de prednisolone pendant 5 jours, sans décroissance","accept":["30 à 40 mg par jour pendant 5 jours","30-40 mg/j 5 jours"],"keywords":["30","5 j"],"explanation":"Elle accélère l'amélioration du VEMS et raccourcit la durée d'hospitalisation ; elle est prescrite au cas par cas.","src":"p. 207, 208"},{"id":"p209-qroc-036","type":"QROC","rank":"A","objective":"p209-obj-14","tags":["suivi"],"difficulty":2,"question":"Dans quel délai le médecin traitant doit-il revoir le patient après une exacerbation de BPCO ?","answer":"Dans la semaine suivant l'exacerbation","accept":["dans la semaine","1 semaine","une semaine","7 jours"],"keywords":["semaine"],"explanation":"Toute exacerbation est un motif de renforcement du suivi clinique et fonctionnel respiratoire (spirométrie à distance).","src":"p. 208"},{"id":"p209-qroc-037","type":"QROC","rank":"B","objective":"p209-obj-04","tags":["étiologie","épidémiologie"],"difficulty":1,"question":"Quel déficit génétique donne un emphysème pan-lobulaire d'autant plus fréquent, précoce et grave que le tabagisme actif est associé ?","answer":"Le déficit en alpha-1 antitrypsine","accept":["alpha-1 antitrypsine","déficit en alpha 1 antitrypsine","alpha1 antitrypsine"],"keywords":["antitrypsine"],"explanation":"Le dosage de l'alpha-1 antitrypsine est recommandé chez tout patient atteint de BPCO.","src":"p. 194, 199"},{"id":"p209-qroc-038","type":"QROC","rank":"B","objective":"p209-obj-08","tags":["complications","suivi"],"difficulty":2,"question":"Quel risque expose l'association d'un corticostéroïde inhalé à un bêta-2-agoniste de longue durée d'action dans la BPCO ?","answer":"Un risque accru d'infections respiratoires parenchymateuses (pneumonies)","accept":["infections respiratoires parenchymateuses","infections respiratoires","pneumonie","pneumonies"],"keywords":["infection"],"explanation":"Une pneumonie sous corticostéroïdes inhalés est un motif de décroissance ou de changement de traitement ; cette association réduit pourtant les symptômes et les exacerbations chez les exacerbateurs fréquents.","src":"p. 200, 202"},{"id":"p209-qroc-039","type":"QROC","rank":"B","objective":"p209-obj-06","tags":["étiologie"],"difficulty":1,"question":"Quelle est l'origine de la majorité des exacerbations de BPCO ?","answer":"Infectieuse (virale, bactérienne ou mixte)","accept":["infectieuse","infection","infections"],"keywords":["infect"],"explanation":"La cause exacte n'est souvent pas identifiée ; une cause environnementale (pic de pollution, tabagisme massif) est parfois en cause.","src":"p. 204-205"},{"id":"p209-qroc-040","type":"QROC","rank":"B","objective":"p209-obj-06","tags":["étiologie"],"difficulty":2,"question":"Quelles sont les trois bactéries les plus souvent en cause dans les exacerbations de BPCO ?","answer":"Haemophilus influenzae, S. pneumoniae, Moraxella catarrhalis","accept":["Haemophilus influenzae, Streptococcus pneumoniae, Moraxella catarrhalis","haemophilus, pneumocoque, moraxella","H. influenzae, S. pneumoniae, M. catarrhalis"],"keywords":["moraxella","pneumo"],"explanation":"Les virus les plus souvent en cause sont la grippe, le VRS, le SARS-CoV-2, les rhinovirus et les adénovirus.","src":"p. 204"},{"id":"p209-qroc-041","type":"QROC","rank":"B","objective":"p209-obj-06","tags":["étiologie","pièges"],"difficulty":2,"question":"Quel germe est rarement impliqué dans les exacerbations, sauf chez les patients sévères (VEMS < 30 %), avec bronchectasies ou ayant reçu une antibiothérapie à large spectre ?","answer":"Pseudomonas aeruginosa","accept":["pseudomonas","pyocyanique"],"keywords":["pseudomonas"],"explanation":"Il est aussi plus probable chez les patients ayant séjourné en milieu hospitalier ou traités de façon chronique par corticothérapie systémique.","src":"p. 205"},{"id":"p209-qroc-042","type":"QROC","rank":"B","objective":"p209-obj-11","tags":["imagerie","clinique"],"difficulty":1,"question":"Comment appelle-t-on l'augmentation du diamètre thoracique antéro-postérieur vue de profil dans la distension de la BPCO ?","answer":"Thorax en tonneau","accept":["thorax en tonneau","tonneau"],"keywords":["tonneau"],"explanation":"Autres signes de distension : aplatissement des coupoles et augmentation des espaces clairs rétro-sternal et rétro-cardiaque (profil), horizontalisation des côtes (face).","src":"p. 198"},{"id":"p209-qroc-043","type":"QROC","rank":"B","objective":"p209-obj-11","tags":["imagerie"],"difficulty":2,"question":"Que traduit une hyperclarté pulmonaire à la radiographie thoracique de face au cours de la BPCO ?","answer":"Une diminution de la vascularisation","accept":["diminution de la vascularisation","raréfaction vasculaire"],"keywords":["vascularisation"],"explanation":"La radiographie thoracique n'a pas d'intérêt dans le diagnostic positif de la BPCO.","src":"p. 198"},{"id":"p209-qroc-044","type":"QROC","rank":"B","objective":"p209-obj-09","tags":["imagerie","complications"],"difficulty":2,"question":"Quelle anomalie identifiée au scanner thoracique d'un patient BPCO doit faire rechercher une coronaropathie non connue ?","answer":"Des calcifications des artères coronaires","accept":["calcifications coronaires","calcifications des coronaires"],"keywords":["calcification"],"explanation":"Le scanner n'est pas systématique mais apporte plus d'informations que la radiographie : caractérisation de l'emphysème, recherche de bronchectasies, dépistage du cancer broncho-pulmonaire.","src":"p. 198-199"},{"id":"p209-qcm-101","type":"QRM","rank":"A","objective":"p209-obj-02","tags":["définition"],"difficulty":1,"stem":"Quelles sont les propositions exactes concernant la définition de la BPCO ?","options":[{"t":"Elle associe des symptômes respiratoires chroniques et un trouble ventilatoire obstructif non complètement réversible.","ok":true,"why":"Au moins un symptôme parmi toux, expectoration, dyspnée d'effort, infections respiratoires basses répétées ou traînantes."},{"t":"Une bronchite chronique suffit à porter le diagnostic, même sans trouble ventilatoire obstructif.","ok":false,"why":"Une bronchite chronique sans TVO n'entre pas dans la définition de la BPCO."},{"t":"Le diagnostic requiert une spirométrie à l'état stable avec VEMS et CVF avant et après bronchodilatateur.","ok":true,"why":"Il est fondé sur la mise en évidence d'un TVO persistant après bronchodilatateur."},{"t":"Un emphysème visible au scanner suffit à porter le diagnostic, même sans trouble ventilatoire obstructif.","ok":false,"why":"Un emphysème sans TVO n'entre pas dans la définition de la BPCO."},{"t":"Le diagnostic est confirmé si le rapport VEMS/CVF se normalise après bronchodilatateur.","ok":false,"why":"Une réversibilité complète écarte la BPCO et oriente vers un asthme."}],"explanation":"BPCO = symptômes respiratoires chroniques + TVO persistant après bronchodilatateur, démontré par une spirométrie à l'état stable.","src":"p. 188-189"},{"id":"p209-qcm-102","type":"QRM","rank":"A","objective":"p209-obj-02","tags":["définition","paraclinique","pièges"],"difficulty":2,"stem":"Concernant le trouble ventilatoire obstructif (TVO) de la BPCO, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Il est défini par un VEMS inférieur à 70 % de la valeur théorique.","ok":false,"why":"Le piège : le pourcentage est le rapport VEMS mesuré / CVF mesurée (× 100), pas un pourcentage d'une valeur théorique."},{"t":"Il est défini par un VEMS/CVF < 0,7 persistant après bronchodilatateur.","ok":true,"why":"Dans la BPCO, le rapport reste < 0,7 après bronchodilatateur, indépendamment de la variation du VEMS."},{"t":"Il est défini par une capacité pulmonaire totale supérieure à 120 % de la théorique.","ok":false,"why":"Une CPT > 120 % avec VR/CPT > 30 % définit la distension pulmonaire, souvent associée au TVO, mais pas le TVO."},{"t":"Il doit être mesuré au cours d'une exacerbation pour être interprétable.","ok":false,"why":"La spirométrie est réalisée à l'état stable, en dehors d'une exacerbation."},{"t":"Une normalisation du rapport VEMS/CVF après bronchodilatateur confirme la BPCO.","ok":false,"why":"Une réversibilité complète écarte le diagnostic de BPCO et oriente vers un asthme."}],"explanation":"TVO = VEMS/CVF < 0,7 (rapport de deux valeurs mesurées) persistant après bronchodilatateur.","trap":"Le 70 % n'est pas un pourcentage de la valeur théorique.","src":"p. 189, 197"},{"id":"p209-qcm-103","type":"QRM","rank":"A","objective":"p209-obj-02","tags":["définition","diagnostic"],"difficulty":2,"stem":"Concernant la bronchite chronique et l'emphysème, quelles propositions sont exactes ?","options":[{"t":"La bronchite chronique est une toux productive d'au moins 3 mois par an pendant 2 années consécutives.","ok":true,"why":"Sa définition est purement clinique : toux productive quotidienne ou quasi quotidienne."},{"t":"La bronchite chronique est définie par des critères anatomopathologiques.","ok":false,"why":"Sa définition est purement clinique ; c'est celle de l'emphysème qui est anatomopathologique."},{"t":"L'emphysème est un élargissement permanent des espaces aériens distaux avec destruction alvéolaire.","ok":true,"why":"Il s'agit d'une destruction des parois alvéolaires, sans fibrose associée."},{"t":"L'emphysème s'affirme sur la radiographie thoracique de face.","ok":false,"why":"Il peut être suspecté sur la radiographie, mais s'affirme sur le scanner (zones d'hypodensité)."},{"t":"La bronchite chronique est rare chez les fumeurs.","ok":false,"why":"Elle concerne environ la moitié des fumeurs."}],"explanation":"Bronchite chronique = définition clinique ; emphysème = définition anatomopathologique, affirmé au scanner ; sans TVO, ni l'une ni l'autre n'entre dans la définition de la BPCO.","src":"p. 189-190"},{"id":"p209-qcm-104","type":"QRM","rank":"A","objective":"p209-obj-05","tags":["diagnostic"],"difficulty":2,"stem":"Pour distinguer l'asthme de la BPCO, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Une réversibilité complète du TVO après bronchodilatateur est en faveur d'une BPCO.","ok":false,"why":"Elle écarte la BPCO et oriente vers un asthme."},{"t":"L'asthme ne s'observe pas chez les fumeurs.","ok":false,"why":"L'asthme existe chez les fumeurs et de nombreux asthmatiques fument."},{"t":"Asthme et BPCO ne peuvent pas être associés chez un même patient.","ok":false,"why":"Les deux maladies peuvent être associées."},{"t":"Une augmentation du VEMS de plus de 400 mL doit faire évoquer un asthme.","ok":true,"why":"L'asthme est aussi évoqué devant des éléments évocateurs dans l'histoire clinique."},{"t":"La spirométrie est normale dans la BPCO et anormale dans l'asthme.","ok":false,"why":"Dans la BPCO la spirométrie n'est jamais normale ; elle peut l'être dans l'asthme (TVO réversible)."}],"explanation":"Le contexte clinique est essentiel : TVO permanent dans la BPCO (fumeur, > 40 ans), TVO réversible dans l'asthme, avec spirométrie parfois normale.","src":"p. 191-192"},{"id":"p209-qcm-105","type":"QRM","rank":"A","objective":"p209-obj-07","tags":["diagnostic","suivi"],"difficulty":2,"stem":"Un patient atteint de BPCO a présenté 3 exacerbations traitées en ville cette année, sans hospitalisation, et a une dyspnée de stade mMRC 1. Quelles propositions sont exactes ?","options":[{"t":"Il est classé dans le groupe E de la classification GOLD.","ok":true,"why":"≥ 2 exacerbations par an ou ≥ 1 avec hospitalisation = groupe E, quelle que soit la dyspnée."},{"t":"Il est classé dans le groupe A car sa dyspnée est de stade mMRC 1.","ok":false,"why":"Le groupe A exige au plus une exacerbation par an sans hospitalisation."},{"t":"Il correspond au phénotype exacerbateur fréquent, facteur de mauvais pronostic.","ok":true,"why":"Ce phénotype fait classer le patient en groupe E."},{"t":"Les groupes C et D de la classification sont encore utilisés séparément.","ok":false,"why":"Les classes C et D ont été abandonnées et réunies en une seule, « E »."},{"t":"Le groupe E est défini uniquement par l'intensité de la dyspnée.","ok":false,"why":"Il est défini par la fréquence ou la gravité des exacerbations."}],"explanation":"Classification clinique GOLD : E = ≥ 2 exacerbations par an ou ≥ 1 avec hospitalisation ; A/B = au plus une exacerbation par an sans hospitalisation, selon mMRC 0-1 ou ≥ 2.","src":"p. 193"},{"id":"p209-qcm-106","type":"QRM","rank":"A","objective":"p209-obj-05","tags":["clinique","pièges"],"difficulty":2,"stem":"Concernant la présentation clinique de la BPCO, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"La dyspnée est un symptôme précoce, bien perçue par le patient.","ok":false,"why":"Elle est tardive et souvent sous-estimée."},{"t":"L'examen physique montre toujours, dès le début de la maladie, une diminution du murmure vésiculaire.","ok":false,"why":"Les signes physiques sont absents pendant des années ou limités à des ronchi ; ils apparaissent souvent après le TVO."},{"t":"Les signes physiques peuvent être absents pendant des années, ou limités à des ronchi.","ok":true,"why":"C'est le piège de la BPCO : un examen normal n'élimine pas le diagnostic."},{"t":"Une toux isolée, sans dyspnée, exclut le diagnostic de BPCO.","ok":false,"why":"La définition exige au moins un symptôme parmi toux, expectoration, dyspnée d'effort, infections respiratoires basses répétées ou traînantes."},{"t":"La dyspnée n'est à rechercher que chez les patients ayant une expectoration.","ok":false,"why":"La dyspnée d'effort est à rechercher chez tout fumeur."}],"explanation":"Dyspnée d'effort tardive et sous-estimée, toux ± expectoration, examen physique longtemps normal ; la confirmation est spirométrique.","src":"p. 188, 196"},{"id":"p209-qcm-107","type":"QRM","rank":"A","objective":"p209-obj-03","tags":["complications","diagnostic"],"difficulty":2,"stem":"Quelles affections font partie des comorbidités fréquemment associées à la BPCO, à rechercher systématiquement ?","options":[{"t":"Hyperthyroïdie","ok":false,"why":"Elle ne fait pas partie des comorbidités citées par le Collège."},{"t":"Affections cardio-vasculaires","ok":true,"why":"Elles sont fréquentes et doivent être recherchées largement (ECG, échocardiographie selon le contexte)."},{"t":"Cancer bronchique","ok":true,"why":"Il fait partie des comorbidités et des principales causes de mortalité."},{"t":"Polyarthrite rhumatoïde","ok":false,"why":"Elle ne fait pas partie des comorbidités citées par le Collège."},{"t":"Dénutrition ou obésité","ok":true,"why":"Avec la dysfonction musculaire squelettique, l'anémie, l'anxiété/dépression et l'ostéoporose."}],"explanation":"Comorbidités à rechercher et prendre en charge chez tout patient BPCO : cardio-vasculaires, cancer bronchique, dénutrition/obésité, dysfonction musculaire, anémie, anxiété/dépression, ostéoporose.","src":"p. 188, 199"},{"id":"p209-qcm-108","type":"QRM","rank":"B","objective":"p209-obj-11","tags":["imagerie"],"difficulty":1,"stem":"Quel(s) signe(s) radiographique(s) évoque(nt) une distension thoracique au cours de la BPCO ?","options":[{"t":"Ascension des coupoles diaphragmatiques (de profil)","ok":false,"why":"Les coupoles sont aplaties."},{"t":"Diminution des espaces clairs rétro-sternal et rétro-cardiaque (de profil)","ok":false,"why":"Ces espaces sont augmentés."},{"t":"Verticalisation des côtes (de face)","ok":false,"why":"Les côtes sont horizontalisées."},{"t":"Hypertransparence due à une augmentation de la vascularisation","ok":false,"why":"L'hyperclarté pulmonaire traduit une diminution de la vascularisation."},{"t":"Thorax en tonneau (de profil)","ok":true,"why":"Augmentation du diamètre thoracique antéro-postérieur."}],"explanation":"La radiographie n'a pas d'intérêt pour le diagnostic positif, mais peut montrer une distension : coupoles aplaties, espaces clairs rétro-sternal et rétro-cardiaque augmentés, thorax en tonneau, côtes horizontalisées, hyperclarté.","src":"p. 198"},{"id":"p209-qcm-109","type":"QRM","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":2,"stem":"Concernant le traitement de fond de la BPCO, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Le sevrage tabagique total est la seule mesure qui modifie de façon certaine l'histoire naturelle.","ok":true,"why":"Il s'agit du sevrage total et définitif, base de la prise en charge quel que soit le stade."},{"t":"Les corticostéroïdes inhalés en monothérapie sont le traitement de fond de référence, comme dans l'asthme.","ok":false,"why":"Ils ne sont pas indiqués en monothérapie dans la BPCO."},{"t":"Les mucomodificateurs et les antileucotriènes sont recommandés pour prévenir les exacerbations.","ok":false,"why":"Ils n'ont aucun intérêt dans la BPCO."},{"t":"Les indications médicamenteuses dépendent avant tout de la sévérité de l'obstruction bronchique.","ok":false,"why":"Elles dépendent des symptômes (dyspnée) et des exacerbations, indépendamment de la sévérité de l'obstruction."},{"t":"La voie orale est la voie recommandée pour les bronchodilatateurs.","ok":false,"why":"Seule la voie inhalée est recommandée."}],"explanation":"Sevrage tabagique, bronchodilatateurs inhalés (puis bithérapie, trithérapie selon symptômes et exacerbations), vaccins, activité physique, réadaptation ; corticostéroïdes inhalés jamais en monothérapie.","src":"p. 199-202"},{"id":"p209-qcm-110","type":"QRM","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":2,"stem":"Concernant les bronchodilatateurs dans la BPCO, quelles propositions sont exactes ?","options":[{"t":"Les bronchodilatateurs de longue durée d'action améliorent la dyspnée, la capacité d'exercice et la qualité de vie.","ok":true,"why":"Ils réduisent aussi le nombre d'exacerbations."},{"t":"Les bêta-2-agonistes de courte durée d'action se prennent systématiquement à heure fixe.","ok":false,"why":"Ils se prennent « à la demande », en cas de dyspnée et lors des exacerbations."},{"t":"Les anticholinergiques et les bêta-2-agonistes ont un effet bronchodilatateur additif.","ok":true,"why":"Leur efficacité sur la fonction respiratoire et la dyspnée est globalement équivalente."},{"t":"Pour prévenir les exacerbations, les anticholinergiques de longue durée sont moins efficaces que les bêta-2-agonistes de longue durée.","ok":false,"why":"Leur efficacité est supérieure à celle des bêta-2-agonistes de longue durée d'action."},{"t":"Seule la voie inhalée est recommandée, avec éducation du patient aux dispositifs d'inhalation.","ok":true,"why":"Il faut aussi vérifier régulièrement la maîtrise de la technique."}],"explanation":"Deux familles (anticholinergiques et bêta-2-agonistes), voie inhalée exclusive, courte durée d'action à la demande, longue durée d'action au long cours.","src":"p. 201-202"},{"id":"p209-qcm-111","type":"QRM","rank":"A","objective":"p209-obj-14","tags":["prévention","traitement"],"difficulty":1,"stem":"Concernant les mesures d'accompagnement de la BPCO, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Les vaccinations ne sont recommandées qu'en cas d'exacerbations fréquentes.","ok":false,"why":"Elles sont recommandées dans tous les cas : grippe (annuelle), pneumocoque, COVID-19."},{"t":"La réadaptation respiratoire n'est proposée qu'aux patients sous oxygénothérapie.","ok":false,"why":"Elle est recommandée dès qu'il existe un handicap, même une dyspnée seule, malgré le traitement."},{"t":"L'activité physique est déconseillée car elle aggrave la dyspnée.","ok":false,"why":"Une activité physique régulière est recommandée ; marcher 30 min par jour ou plus de 2 h par semaine diminue la mortalité."},{"t":"La vaccination anti-COVID-19 est indiquée chez tous les patients BPCO.","ok":true,"why":"Avec la vaccination grippale annuelle et la vaccination anti-pneumococcique."},{"t":"Une spirométrie tous les 5 ans suffit au suivi.","ok":false,"why":"Une EFR annuelle au minimum est recommandée."}],"explanation":"Dans tous les cas : aide au sevrage tabagique, vaccinations, activité physique, suivi nutritionnel, réadaptation si handicap persistant, EFR annuelle au minimum.","src":"p. 201-203"},{"id":"p209-qcm-112","type":"QRM","rank":"A","objective":"p209-obj-12","tags":["définition","urgence"],"difficulty":2,"stem":"Quelles propositions sont exactes concernant l'exacerbation aiguë de BPCO ?","options":[{"t":"Elle associe une augmentation de la dyspnée et/ou de la toux et des expectorations, s'aggravant en moins de 14 jours.","ok":true,"why":"Elle peut s'associer à une tachypnée et/ou une tachycardie."},{"t":"Elle est dite sévère lorsque les symptômes durent plus de 14 jours.","ok":false,"why":"Une exacerbation est sévère lorsqu'elle nécessite une hospitalisation."},{"t":"Elle est dite sévère lorsqu'elle nécessite une hospitalisation.","ok":true,"why":"Définition des exacerbations sévères."},{"t":"Elle est toujours d'origine bactérienne.","ok":false,"why":"La majorité est infectieuse (virale, bactérienne ou mixte), mais la cause n'est souvent pas identifiée."},{"t":"Le pronostic vital peut être engagé en cas d'hypoxémie profonde et/ou d'acidose respiratoire décompensée.","ok":true,"why":"Acidose respiratoire décompensée : pH ≤ 7,35."}],"explanation":"Exacerbation = majoration de la dyspnée, de la toux et/ou de l'expectoration en moins de 14 jours ; sévère si hospitalisation ; hypoxémie profonde et acidose décompensée engagent le pronostic vital.","src":"p. 189, 204"},{"id":"p209-qcm-113","type":"QRM","rank":"A","objective":"p209-obj-12","tags":["urgence","pièges"],"difficulty":2,"stem":"Quels éléments sont des critères d'hospitalisation d'une exacerbation de BPCO ?","options":[{"t":"Un jeune âge, sans comorbidité","ok":false,"why":"Ce sont l'âge avancé et la fragilité qui sont retenus."},{"t":"Une absence de soutien à domicile","ok":true,"why":"Elle figure parmi les critères d'hospitalisation."},{"t":"Une oxygénothérapie au long cours ou une ventilation assistée à domicile","ok":true,"why":"Elles figurent parmi les critères d'hospitalisation."},{"t":"Une expectoration verdâtre isolée chez un patient sans signe de gravité","ok":false,"why":"Sans signe de gravité, l'exacerbation peut être prise en charge en ville."},{"t":"Un antécédent de séjour en réanimation pour exacerbation","ok":true,"why":"Il fait partie des critères d'hospitalisation."}],"explanation":"Hospitalisation : signes de détresse respiratoire aiguë, aggravation rapide, dyspnée de base importante, échec du traitement initial, incertitude diagnostique, âge avancé, absence de soutien, OLD ou ventilation à domicile, antécédent de réanimation, comorbidités.","src":"p. 204"},{"id":"p209-qcm-114","type":"QRM","rank":"A","objective":"p209-obj-13","tags":["traitement","urgence"],"difficulty":2,"stem":"Un patient BPCO est hospitalisé pour une exacerbation sévère. Quelles mesures sont adaptées ?","options":[{"t":"Bêta-2-agonistes en nébulisation, éventuellement associés à un anticholinergique.","ok":true,"why":"La nébulisation est le mode d'administration privilégié à l'hôpital."},{"t":"Antitussifs pour calmer la toux.","ok":false,"why":"Antitussifs et neurosédatifs sont contre-indiqués."},{"t":"Oxygène titré pour obtenir une SpO2 entre 88 et 92 %.","ok":true,"why":"Avec surveillance de la SpO2 et des gaz du sang."},{"t":"Oxygène à haut débit visant une SpO2 de 100 %.","ok":false,"why":"La cible est de 88 à 92 % ; en cas d'hypercapnie, l'oxygène peut aggraver l'acidose respiratoire."},{"t":"Héparine de bas poids moléculaire préventive, en l'absence d'insuffisance rénale.","ok":true,"why":"Prévention de la maladie thrombo-embolique chez les malades hospitalisés."}],"explanation":"À l'hôpital : bronchodilatateurs nébulisés, oxygène (SpO2 88-92 %), antibiotiques selon les critères, corticothérapie courte au cas par cas, HBPM préventive, ventilation si acidose respiratoire.","src":"p. 206-208"},{"id":"p209-qcm-115","type":"QRM","rank":"A","objective":"p209-obj-13","tags":["traitement","urgence"],"difficulty":1,"stem":"Concernant l'oxygénothérapie au cours d'une exacerbation de BPCO, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Le débit est titré pour obtenir une SpO2 supérieure à 98 %.","ok":false,"why":"La SpO2 cible est comprise entre 88 et 92 %."},{"t":"Il faut limiter l'oxygène, même en cas d'hypoxémie profonde, pour éviter l'hypercapnie.","ok":false,"why":"L'hypoxémie mal tolérée ou profonde est un signe de gravité majeur et doit toujours être corrigée par des débits adéquats."},{"t":"En cas d'hypercapnie, on surveille les gaz du sang : l'oxygène peut aggraver l'acidose.","ok":true,"why":"C'est la précaution à prendre chez le patient hypercapnique."},{"t":"La mise en route d'une oxygénothérapie peut toujours se faire en ambulatoire, sans hospitalisation.","ok":false,"why":"Le recours à une oxygénothérapie (ou la modification de son débit chez un patient sous OLD) est un motif d'hospitalisation."},{"t":"La surveillance de la SpO2 suffit, sans gaz du sang.","ok":false,"why":"La surveillance associe SpO2 et gaz du sang."}],"explanation":"SpO2 cible 88-92 %, correction de toute hypoxémie mal tolérée, surveillance gazométrique en cas d'hypercapnie.","src":"p. 207-208"},{"id":"p209-qcm-116","type":"QRM","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":2,"stem":"Concernant l'antibiothérapie d'une exacerbation de BPCO, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Elle est systématique dans toute exacerbation, quelles que soient l'expectoration et la gravité.","ok":false,"why":"Elle est indiquée si expectoration franchement purulente, BPCO très sévère (VEMS < 30 %) ou signes de gravité."},{"t":"Elle est indiquée si l'expectoration est franchement purulente, BPCO très sévère ou signes de gravité.","ok":true,"why":"Première intention : amoxicilline ± acide clavulanique, pristinamycine, macrolides."},{"t":"Les quinolones actives sur le pneumocoque sont recommandées en première intention dans toute exacerbation.","ok":false,"why":"Elles sont réservées à des cas particuliers (échec d'antibiothérapies antérieures...)."},{"t":"Sa durée habituelle est de 14 jours.","ok":false,"why":"Le traitement est prescrit pour 5 à 7 jours, réévalué à J2 ou J3."},{"t":"Les aminosides constituent le traitement de première intention.","ok":false,"why":"Les autres familles que celles citées ne sont pas recommandées."}],"explanation":"Antibiotiques si purulence franche, VEMS < 30 % ou signes de gravité ; amoxicilline ± acide clavulanique, pristinamycine ou macrolides pendant 5 à 7 jours, réévalués à J2-J3.","src":"p. 206-207"},{"id":"p209-qcm-117","type":"QRM","rank":"B","objective":"p209-obj-06","tags":["étiologie"],"difficulty":2,"stem":"À propos des facteurs précipitants des exacerbations de BPCO, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"La majorité des exacerbations est d'origine non infectieuse, notamment liée à la pollution.","ok":false,"why":"La majorité est d'origine infectieuse (virale, bactérienne ou mixte)."},{"t":"Pseudomonas aeruginosa est le germe le plus souvent en cause chez tous les patients BPCO.","ok":false,"why":"Il est rarement impliqué, sauf chez les patients sévères (VEMS < 30 %) ou ayant des bronchectasies."},{"t":"La cause exacte de l'exacerbation est presque toujours identifiée dès la prise en charge initiale.","ok":false,"why":"La cause exacte n'est souvent pas identifiée."},{"t":"La pollution atmosphérique particulaire n'a aucun rôle dans le déclenchement des exacerbations.","ok":false,"why":"Elle joue un rôle dans le déclenchement d'exacerbations."},{"t":"Les bactéries les plus fréquentes : H. influenzae, S. pneumoniae et M. catarrhalis.","ok":true,"why":"Les virus les plus fréquents sont la grippe, le VRS, le SARS-CoV-2, les rhinovirus et les adénovirus."}],"explanation":"Exacerbation le plus souvent infectieuse ; la purulence de l'expectoration est le principal argument en faveur d'une infection bactérienne.","src":"p. 204-205"},{"id":"p209-qcm-118","type":"QRM","rank":"B","objective":"p209-obj-04","tags":["épidémiologie"],"difficulty":1,"stem":"Concernant l'épidémiologie de la BPCO, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"La BPCO concerne moins de 1 % de la population française de plus de 45 ans.","ok":false,"why":"Elle concerne 5 à 10 % des plus de 45 ans, soit 2,5 à 3,5 millions de sujets."},{"t":"Le tabagisme est retrouvé chez moins de la moitié des patients atteints de BPCO en France.","ok":false,"why":"Plus de 80 % des patients atteints de BPCO en France sont fumeurs."},{"t":"La BPCO est la 4e cause de mortalité dans le monde.","ok":true,"why":"Sa prévalence augmente et elle devrait devenir la 3e cause de mortalité d'ici 2030."},{"t":"La pollution domestique par les fumées de biomasse est le principal facteur de risque en France.","ok":false,"why":"Elle est un facteur de risque dans les pays émergents ; le tabac est de loin le principal facteur de risque en France."},{"t":"La BPCO est une maladie bien connue du grand public et de la plupart des professionnels de santé.","ok":false,"why":"Cette maladie est méconnue du grand public et de nombreux professionnels de santé."}],"explanation":"Problème de santé publique majeur : 5 à 10 % des plus de 45 ans en France, plus de 18 000 décès liés à la BPCO en 2022, 4e cause de mortalité mondiale.","src":"p. 194"},{"id":"p209-qru-101","type":"QRU","rank":"A","objective":"p209-obj-07","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Un homme de 66 ans, fumeur (45 paquets-années), consulte pour une dyspnée à la marche rapide. La spirométrie post-bronchodilatateur montre un rapport VEMS/CVF à 0,58 et un VEMS à 62 % de la valeur prédite. Quel est le grade de sévérité de l'obstruction bronchique ?","options":[{"t":"GOLD 1 (légère)","ok":false,"why":"GOLD 1 correspond à un VEMS ≥ 80 %."},{"t":"GOLD 2 (modérée)","ok":true,"why":"VEMS compris entre 50 et 79 % de la valeur prédite."},{"t":"GOLD 3 (sévère)","ok":false,"why":"GOLD 3 correspond à un VEMS de 30 à 49 %."},{"t":"GOLD 4 (très sévère)","ok":false,"why":"GOLD 4 correspond à un VEMS < 30 %."},{"t":"Pas de BPCO, car le VEMS est supérieur à 50 %","ok":false,"why":"Le diagnostic repose sur le rapport VEMS/CVF < 0,7 persistant après bronchodilatateur ; le VEMS sert à grader la sévérité."}],"explanation":"TVO confirmé (VEMS/CVF < 0,7 post-BD) ; la sévérité se juge sur le VEMS post-BD : ≥ 80 % GOLD 1, 50-79 % GOLD 2, 30-49 % GOLD 3, < 30 % GOLD 4.","src":"p. 192"},{"id":"p209-qru-102","type":"QRU","rank":"A","objective":"p209-obj-05","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Une femme de 48 ans, fumeuse, décrit des symptômes variables avec des périodes asymptomatiques. La spirométrie montre un rapport VEMS/CVF à 0,62 avant bronchodilatateur et à 0,76 après, avec un gain de VEMS de 450 mL. Quel diagnostic est orienté ?","options":[{"t":"Asthme","ok":true,"why":"Réversibilité complète (rapport normalisé) et très importante (> 400 mL) : elle écarte la BPCO et oriente vers un asthme."},{"t":"BPCO modérée","ok":false,"why":"Le TVO de la BPCO n'est pas complètement réversible."},{"t":"Dilatation des bronches","ok":false,"why":"Aucun élément ne l'évoque ; la réversibilité oriente vers un asthme."},{"t":"BPCO avec emphysème","ok":false,"why":"L'emphysème s'accompagne d'une obstruction persistante, non réversible."},{"t":"BPCO avec phénotype exacerbateur fréquent","ok":false,"why":"Ce phénotype se définit par les exacerbations ; ici le TVO est complètement réversible."}],"explanation":"Une réversibilité complète du TVO (VEMS/CVF > 0,7 après bronchodilatateur) écarte la BPCO ; une augmentation du VEMS de plus de 400 mL fait évoquer un asthme.","src":"p. 189, 191"},{"id":"p209-qru-103","type":"QRU","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":2,"stem":"Un patient atteint de BPCO, traité par l'association d'un bêta-2-agoniste et d'un anticholinergique de longue durée d'action, garde des exacerbations malgré une bonne observance. Quelle modification est envisagée ?","options":[{"t":"Arrêt des bronchodilatateurs et passage à un corticostéroïde inhalé seul","ok":false,"why":"Les corticostéroïdes inhalés en monothérapie ne sont pas indiqués dans la BPCO."},{"t":"Ajout d'un mucomodificateur","ok":false,"why":"Les mucomodificateurs n'ont aucun intérêt dans la BPCO."},{"t":"Ajout d'un antileucotriène","ok":false,"why":"Les antileucotriènes n'ont aucun intérêt dans la BPCO."},{"t":"Triple thérapie avec ajout d'un corticostéroïde inhalé","ok":true,"why":"Une triple thérapie est considérée en cas de persistance d'exacerbations malgré une bithérapie."},{"t":"Corticothérapie orale au long cours","ok":false,"why":"Les corticostéroïdes systémiques sont réservés aux exacerbations, en cure courte."}],"explanation":"Séquence : bronchodilatateur, puis bithérapie, puis éventuellement triple thérapie (bêta-2 + anticholinergique + corticostéroïde inhalé) si les exacerbations persistent.","src":"p. 188, 200, 202"},{"id":"p209-qru-104","type":"QRU","rank":"A","objective":"p209-obj-13","tags":["traitement","urgence"],"difficulty":2,"stem":"Un patient atteint de BPCO connue présente depuis 3 jours une majoration de sa dyspnée avec une expectoration franchement purulente, sans signe de gravité. Il est pris en charge en ville. Quel traitement est adapté ?","options":[{"t":"Corticothérapie systémique d'emblée en première intention, sans bronchodilatateur","ok":false,"why":"À domicile, la corticothérapie n'est envisagée qu'en seconde intention ; les bronchodilatateurs sont le traitement essentiel."},{"t":"Antitussifs et neurosédatifs","ok":false,"why":"Ils sont contre-indiqués."},{"t":"Bronchodilatateurs inhalés et antibiothérapie (amoxicilline)","ok":true,"why":"Bronchodilatateurs en traitement essentiel ; antibiotique (amoxicilline ± acide clavulanique, pristinamycine ou macrolide) car l'expectoration est franchement purulente."},{"t":"Hospitalisation systématique en réanimation pour surveillance","ok":false,"why":"Sans signe de gravité, l'exacerbation est prise en charge en ville."},{"t":"Ventilation non invasive à domicile en urgence","ok":false,"why":"Elle n'est indiquée qu'en cas d'acidose respiratoire (pH < 7,35)."}],"explanation":"Exacerbation sans gravité : bronchodilatateurs inhalés (courte durée d'action), antibiotique si expectoration franchement purulente, corticoïdes en seconde intention si absence d'amélioration à 48 h.","src":"p. 206-208"},{"id":"p209-qru-105","type":"QRU","rank":"A","objective":"p209-obj-13","tags":["traitement","urgence"],"difficulty":2,"stem":"Un patient BPCO hospitalisé pour exacerbation devient somnolent ; les gaz du sang montrent un pH à 7,28 avec hypercapnie malgré le traitement initial. Quelle assistance ventilatoire est proposée en première intention ?","options":[{"t":"Intubation d'emblée avec ventilation invasive","ok":false,"why":"En première intention, une ventilation non invasive est proposée."},{"t":"Oxygène à haut débit seul","ok":false,"why":"Une acidose respiratoire (pH < 7,35) impose une assistance ventilatoire mécanique."},{"t":"Corticothérapie systémique seule","ok":false,"why":"Elle accélère l'amélioration du VEMS mais ne remplace pas la ventilation en cas d'acidose respiratoire."},{"t":"Surveillance simple : l'acidose se corrige spontanément","ok":false,"why":"Une acidose respiratoire (pH < 7,35) justifie une ventilation mécanique."},{"t":"Ventilation non invasive par masque facial","ok":true,"why":"Elle est indiquée en cas d'acidose respiratoire (pH < 7,35), en première intention."}],"explanation":"pH < 7,35 : ventilation mécanique, d'abord non invasive par masque facial.","src":"p. 208"},{"id":"p209-qru-106","type":"QRU","rank":"A","objective":"p209-obj-14","tags":["traitement"],"difficulty":2,"stem":"Un patient BPCO est hospitalisé pour une exacerbation sévère. Quelle corticothérapie systémique peut être prescrite, au cas par cas ?","options":[{"t":"0,5 mg/kg/j de prednisone pendant 15 jours","ok":false,"why":"C'est le schéma du test aux corticoïdes (réversibilité du TVO), pas celui de l'exacerbation."},{"t":"1 mg/kg/j pendant 3 semaines avec décroissance progressive","ok":false,"why":"La cure est courte et sans décroissance : 30-40 mg/j pendant 5 jours."},{"t":"Aucune corticothérapie systémique n'est jamais envisagée dans l'exacerbation","ok":false,"why":"Elle accélère l'amélioration du VEMS et raccourcit l'hospitalisation ; elle est prescrite au cas par cas."},{"t":"30 à 40 mg/j de prednisolone pendant 5 jours, sans décroissance","ok":true,"why":"Dose modérée, durée courte."},{"t":"Corticothérapie inhalée en monothérapie à forte dose pendant 15 jours","ok":false,"why":"Les corticostéroïdes inhalés en monothérapie ne sont pas indiqués dans la BPCO."}],"explanation":"À l'hôpital : 30-40 mg/j de prednisolone pendant 5 jours, sans décroissance ; à domicile, seulement en seconde intention si absence d'amélioration à 48 h.","src":"p. 207, 208"},{"id":"p209-qru-107","type":"QRU","rank":"A","objective":"p209-obj-12","tags":["diagnostic","urgence"],"difficulty":2,"stem":"Un patient BPCO présente une aggravation de sa dyspnée avec une fièvre à 39 °C et des crépitants en foyer ; l'imagerie thoracique objective un syndrome alvéolaire. Quel diagnostic est évoqué ?","options":[{"t":"Pneumonie aiguë communautaire","ok":true,"why":"Foyer de crépitants, fièvre ≥ 38,5 °C, syndrome alvéolaire : on traite comme une PAC, avec renforcement du traitement bronchodilatateur si nécessaire."},{"t":"Exacerbation de BPCO simple","ok":false,"why":"Les diagnostics différentiels doivent être distingués de l'exacerbation car ils requièrent un traitement spécifique."},{"t":"Œdème pulmonaire cardiogénique","ok":false,"why":"On l'évoque devant la clinique, la radiographie, l'ECG et la biologie (BNP, troponine)."},{"t":"Embolie pulmonaire","ok":false,"why":"Diagnostic difficile, nécessitant une angio-TDM thoracique."},{"t":"Pneumothorax","ok":false,"why":"Autre diagnostic différentiel de l'exacerbation, mais sans foyer de crépitants ni syndrome alvéolaire fébrile."}],"explanation":"Diagnostics différentiels d'une majoration de la dyspnée du BPCO : pneumonie (crépitants en foyer, fièvre ≥ 38,5 °C, syndrome alvéolaire), œdème pulmonaire, embolie pulmonaire, pneumothorax, médicaments, traumatisme, chirurgie.","src":"p. 205"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p209-pareto","points":[{"id":"p209-par-01","rank":"A","cat":"définition","text":"**BPCO** = symptômes respiratoires chroniques + **TVO non complètement réversible** (**VEMS/CVF < 0,7** après bronchodilatateur)","src":"p. 188-189"},{"id":"p209-par-02","rank":"A","cat":"piège","text":"**Spirométrie** à l'état stable, avant/après bronchodilatateur = **obligatoire** au diagnostic ; piège : le 70 % = VEMS/CVF mesurés, **pas % de la théorique**","src":"p. 189, 197"},{"id":"p209-par-03","rank":"A","cat":"définition","text":"**Bronchite chronique** = toux productive **≥ 3 mois/an, 2 ans de suite** ; emphysème = anatomopathologique (**scanner**) ; sans TVO ≠ BPCO","src":"p. 189-190"},{"id":"p209-par-04","rank":"A","cat":"clinique","text":"**Tabac** = 1er facteur de risque (> 80 %) ; **dyspnée d'effort** = symptôme principal, tardif, sous-estimé ; examen physique **normal** longtemps","src":"p. 188, 194, 196"},{"id":"p209-par-05","rank":"A","cat":"piège","text":"DD : **asthme**, **dilatation des bronches** ; réversibilité **complète** (VEMS/CVF > 0,7) = asthme ; significative = VEMS > 200 mL et > 12 %","src":"p. 188-189, 191"},{"id":"p209-par-06","rank":"A","cat":"gravité","text":"GOLD 1-4 (VEMS post-BD) : **≥ 80 % / 50-79 % / 30-49 % / < 30 %**","src":"p. 192"},{"id":"p209-par-07","rank":"A","cat":"gravité","text":"GOLD A/B/E : mMRC 0-1 (A), ≥ 2 (B) ; **E** = **≥ 2 exacerbations/an** ou **≥ 1 avec hospitalisation**","src":"p. 193"},{"id":"p209-par-08","rank":"A","cat":"clinique","text":"Comorbidités à chercher : **cardio-vasculaires**, **cancer bronchique**, dénutrition/obésité, dysfonction musculaire, anémie, anxiété/dépression, ostéoporose","src":"p. 188, 199"},{"id":"p209-par-09","rank":"A","cat":"traitement","text":"Traitement de fond : **arrêt du tabac** (seule mesure modifiant l'évolution), bronchodilatateur → **bithérapie** → **trithérapie**","src":"p. 199-202"},{"id":"p209-par-10","rank":"A","cat":"traitement","text":"**CSI seuls** non indiqués ; CSI + BDLA si **exacerbateurs fréquents** (risque de pneumonie) ; éosinophiles < 300/mm³ = pas de CSI","src":"p. 200-202"},{"id":"p209-par-11","rank":"A","cat":"prévention","text":"**Vaccins** grippe (annuel), pneumocoque, COVID-19 ; **réadaptation** dès qu'il y a un handicap ; **marche 30 min/j**","src":"p. 202-203"},{"id":"p209-par-12","rank":"A","cat":"gravité","text":"**Exacerbation** = aggravation en **< 14 jours** ; **sévère** = hospitalisation ; vital : hypoxémie profonde, acidose décompensée (pH ≤ 7,35)","src":"p. 189, 204"},{"id":"p209-par-13","rank":"A","cat":"étiologie","text":"Exacerbation surtout **infectieuse** ; **purulence** = argument bactérien ; DD : **PAC, OAP, embolie pulmonaire**, pneumothorax","src":"p. 204-205"},{"id":"p209-par-14","rank":"A","cat":"traitement","text":"Exacerbation : **bronchodilatateurs inhalés**, **O2 pour SpO2 88-92 %**, **ATB** si purulence, VEMS < 30 % ou gravité (5-7 j)","src":"p. 206-207"},{"id":"p209-par-15","rank":"A","cat":"traitement","text":"Corticoïdes **30-40 mg/j 5 j** à l'hôpital (domicile : si pas d'amélioration à **48 h**) ; acidose pH < 7,35 → **VNI** par masque facial","src":"p. 207-208"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
